    bands=[]
    for b in v.findall('band'):
        bands.append((b.get('from'), b.get('to'), int(b.get('cents_per_kwh'))))
    vers.append((v.get('valid_from'), v.get('valid_to'), bands))
def tomin(s):
    h,m=s.split(':'); return int(h)*60+int(m)
def price(bands, minute):
    minute%=1440
    for f,t,c in bands:
        a,b=tomin(f),tomin(t)
        if a<b:
            if a<=minute<b: return c
        else:
            if minute>=a or minute<b: return c
    raise Exception('no band')
def ver_for(date):
    for vf,vt,bands in vers:
        if vf<=date<=vt: return bands
    return None
rows=list(csv.DictReader(open('settlements.csv')))
print(len(rows), collections.Counter(r['depot'] for r in rows))
bydepot=collections.defaultdict(list)
for r in rows: bydepot[r['depot']].append(r)
for depot,rs in sorted(bydepot.items()):
    ok=[]
    for k in range(96):
        good=True
        for r in rs:
            bands=ver_for(r['settled_date'])
            st=datetime.fromisoformat(r['start']); en=datetime.fromisoformat(r['end'])
            nsl=int((en-st).total_seconds()//900)
            tot=0
            for i in range(nsl):
                t=st+timedelta(minutes=15*i)
                tot+=price(bands, t.hour*60+t.minute+k*15)
