def solve(self, source, sink):
    """Min cost circulation: augment while the cheapest path is negative."""
    pot = self.initial_potentials(source)
    to, cap, cost, graph = self.to, self.cap, self.cost, self.graph
    nodes = self.nodes
    while True:
        dist = [None] * nodes
        prev = [-1] * nodes
        dist[source] = 0
        heap = [(0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            du = dist[u]
            if du is None or d > du:
                continue
            pu = pot[u]
            for eid in graph[u]:
                if cap[eid] <= 0:
                    continue
                v = to[eid]
                nd = d + cost[eid] + pu - pot[v]
                if dist[v] is None or nd < dist[v]:
                    dist[v] = nd
                    prev[v] = eid
                    heapq.heappush(heap, (nd, v))
        if dist[sink] is None:
            break
        if dist[sink] + pot[sink] - pot[source] >= 0:
            break
        for v in range(nodes):
            if dist[v] is not None:
                pot[v] += dist[v]
        delta = None
        v = sink
        while v != source:
            eid = prev[v]
