def solve(self, source, sink):
    """Min cost circulation by primal-dual: a blocking flow per distance."""
    pot = self.initial_potentials(source)
    to, cap, cost, graph = self.to, self.cap, self.cost, self.graph
    nodes = self.nodes
    while True:
        dist = [None] * nodes
        dist[source] = 0
        heap = [(0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            du = dist[u]
            if du is None or d > du:
                continue
            pu = pot[u]
            for eid in graph[u]:
                if cap[eid] <= 0:
                    continue
                v = to[eid]
                nd = d + cost[eid] + pu - pot[v]
                if dist[v] is None or nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        if dist[sink] is None or dist[sink] + pot[sink] - pot[source] >= 0:
            break
        for v in range(nodes):
            if dist[v] is not None:
                pot[v] += dist[v]
        self.blocking_flow(source, sink, pot)
    return pot

def blocking_flow(self, source, sink, pot):
    """Max flow from source to sink over arcs of zero reduced cost."""
    to, cap, cost, graph = self.to, self.cap, self.cost, self.graph
    nodes = self.nodes
    while True:
        admissible = [[] for _ in range(nodes)]
        for u in range(nodes):
            pu = pot[u]
            adj = admissible[u]
            for eid in graph[u]:
                if cap[eid] > 0 and cost[eid] + pu - pot[to[eid]] == 0:
                    adj.append(eid)
        level = [-1] * nodes
        level[source] = 0
        queue = deque([source])
        while queue:
            u = queue.popleft()
            lv = level[u] + 1
            for eid in admissible[u]:
                v = to[eid]
                if level[v] < 0:
                    level[v] = lv
                    queue.append(v)
        if level[sink] < 0:
            return
        it = [0] * nodes
        while True:
            # one augmenting path along the level graph
            path = []
            u = source
            while True:
                if u == sink:
                    break
                adj = admissible[u]
                advanced = False
                while it[u] < len(adj):
                    eid = adj[it[u]]
                    v = to[eid]
                    if cap[eid] > 0 and level[v] == level[u] + 1:
                        path.append(eid)
                        u = v
                        advanced = True
                        break
                    it[u] += 1
                if advanced:
                    continue
                if u == source:
                    break
                level[u] = -1
                eid = path.pop()
                u = to[eid ^ 1]
                it[u] += 1
            if u != sink:
                break
            delta = min(cap[eid] for eid in path)
            for eid in path:
                cap[eid] -= delta
                cap[eid ^ 1] += delta
            for eid in path:
                if cap[eid] == 0:
                    break

