"""Brute-force check of solve_plan on small random instances."""
import itertools
import random
import sys

sys.path.insert(0, '/app/out')
import derive_report as dr


def brute(buses, depot_names, depot_cap, feeder, prices, nslots):
    bus_ids = sorted(buses)
    options = []
    for b in bus_ids:
        bus = buses[b]
        per_slot = []
        for s in range(nslots):
            if s in bus['window']:
                per_slot.append(range(bus['max'] + 1))
            else:
                per_slot.append([0])
        combos = [c for c in itertools.product(*per_slot) if sum(c) <= bus['need']]
        options.append(combos)
    best = None
    best_key = None
    for assign in itertools.product(*options):
        ok = True
        for s in range(nslots):
            tot = 0
            for d in depot_names:
                dt = sum(assign[i][s] for i, b in enumerate(bus_ids)
                         if buses[b]['depot'] == d)
                if dt > depot_cap[d][s]:
                    ok = False
                    break
                tot += dt
            if not ok or tot > feeder[s]:
                ok = False
                break
        if not ok:
            continue
        wu = 0
        cost = 0
        moved = 0
        for i, b in enumerate(bus_ids):
            bus = buses[b]
            delivered = sum(assign[i])
            wu += bus['weight'] * (bus['need'] - delivered)
            for s in range(nslots):
                cost += prices[bus['depot']][s] * assign[i][s]
                pub = bus['pub'].get(s, 0)
                if pub > assign[i][s]:
                    moved += pub - assign[i][s]
        lex = tuple(assign[i][s] for s in range(nslots)
                    for i in range(len(bus_ids)))
        key = (wu, cost, moved, tuple(-v for v in lex))
        if best_key is None or key < best_key:
            best_key = key
            best = assign
    return best, best_key


def run(seed):
    rnd = random.Random(seed)
    nslots = rnd.randint(2, 3)
    nbus = rnd.randint(2, 3)
    depot_names = ['A', 'B'][:rnd.randint(1, 2)]
    buses = {}
    for i in range(nbus):
        bid = 'B%d' % (i + 1)
        start = rnd.randint(0, nslots - 1)
        end = rnd.randint(start + 1, nslots)
        window = list(range(start, end))
        mx = rnd.randint(1, 3)
        need = rnd.randint(0, mx * nslots)
        pub = {}
        for s in window:
            if rnd.random() < 0.4:
                pub[s] = rnd.randint(0, mx + 1)
        cls = rnd.choice(['public', 'commercial'])
        buses[bid] = {
            'bus_id': bid,
            'depot': rnd.choice(depot_names),
            'class': cls,
            'weight': 4 if cls == 'public' else 1,
            'max': mx,
            'need': need,
            'window': window,
            'pub': pub,
        }
    depot_cap = {d: [rnd.randint(0, 5) for _ in range(nslots)]
                 for d in depot_names}
    feeder = [rnd.randint(0, 7) for _ in range(nslots)]
    prices = {d: [rnd.choice([0, 1, 2, 5]) for _ in range(nslots)]
              for d in depot_names}

    plan = dr.solve_plan(buses, depot_names, depot_cap, feeder, prices, nslots)
    bus_ids = sorted(buses)
    mine = tuple(tuple(plan[b].get(s, 0) for s in range(nslots))
                 for b in bus_ids)
    best, best_key = brute(buses, depot_names, depot_cap, feeder, prices, nslots)
    if best is None:
        best = tuple(tuple(0 for _ in range(nslots)) for _ in bus_ids)
    if mine != tuple(tuple(x) for x in best):
        print('MISMATCH seed', seed)
        print(' buses', {b: {k: v for k, v in buses[b].items()} for b in bus_ids})
        print(' depot_cap', depot_cap, 'feeder', feeder, 'prices', prices)
        print(' mine', mine)
        print(' best', best, best_key)
        return False
    return True


bad = 0
for seed in range(int(sys.argv[1]) if len(sys.argv) > 1 else 300):
    if not run(seed):
        bad += 1
        if bad > 3:
            break
print('done, mismatches', bad)

"""Independent checks of the written reports against the data folder."""
import csv
