bands = [(12 * 60, 16 * 60, 31), (16 * 60, 22 * 60, 27), (22 * 60, 6 * 60, 14),
         (6 * 60, 12 * 60, 22)]


def price_at(minute):
    minute %= 1440
    for a, b, c in bands:
        if a < b:
            if a <= minute < b:
                return c
        else:
            if minute >= a or minute < b:
                return c
    raise AssertionError


t0 = datetime.fromisoformat(slots[0])
for depot, k in (('North', 0), ('South', 0), ('West', 0), ('East', 28)):
