    if d['service_date'] == '2026-03-15':
        trip[d['bus_id']] = trip.get(d['bus_id'], 0) + d['kwh']
extra = {'B1051': 35, 'B1179': 20, 'B1292': 75}

feeder_used = [0] * nslots
depot_used = {d: [0] * nslots for d in regions}
class_used = {c: [0] * nslots for c in segments}
cost_total = 0
moved_total = 0
wunmet = 0
short = 0
changed_n = 0
contracts = {c['contract_id']: c['class']
