assert sum(doc['energy_kwh'] for doc in regions.values()) == sum(feeder_used)
assert sum(doc['energy_kwh'] for doc in segments.values()) == sum(feeder_used)
assert dq['rejected'] == sorted(dq['rejected'], key=lambda r: (r['file'], r['line']))
print('all checks passed; energy', sum(feeder_used), 'cost', cost_total,
      'moved', moved_total, 'wunmet', wunmet)

